const page = figma.root.children.find(c => c.id === "0:1");
if (!page) {
  figma.closePlugin("Page 0:1 not found");
} else {
  // Let's inspect the children and text contents
  const textNodes = page.findAll(n => n.type === "TEXT");
  const result = textNodes.map(t => `[${t.name}]: ${t.characters}`).join("\n\n");
  figma.closePlugin(result);
}

const fPage = figma.root.children.find(c => c.id === "1:2");
const cPage = figma.root.children.find(c => c.id === "1:3");
const mPage = figma.root.children.find(c => c.id === "1:4");

function dumpNode(node, depth = 0) {
  let res = " ".repeat(depth * 2) + `[${node.type}] ${node.name} (${node.id})\n`;
  if ("children" in node && depth < 2) {
    for (const child of node.children) {
      res += dumpNode(child, depth + 1);
    }
  }
  return res;
}

let out = "=== Foundations ===\n";
if (fPage) {
  for (const child of fPage.children) out += dumpNode(child);
}
out += "\n=== Components ===\n";
if (cPage) {
  for (const child of cPage.children) out += dumpNode(child);
}
out += "\n=== Media ===\n";
if (mPage) {
  for (const child of mPage.children) out += dumpNode(child);
}

figma.closePlugin(out.slice(0, 15000));

const cPage = figma.root.children.find(c => c.id === "1:3");
if (!cPage) {
  figma.closePlugin("Components page not found");
} else {
  const btn = cPage.findOne(n => n.type === "COMPONENT" && n.name === "Button");
  const tf = cPage.findOne(n => n.type === "COMPONENT" && n.name === "Text Field");

  function inspectProps(node) {
    if (!node) return "null";
    return `Name: ${node.name}, Id: ${node.id}, Size: ${node.width}x${node.height}, Padding: L:${node.paddingLeft} R:${node.paddingRight} T:${node.paddingTop} B:${node.paddingBottom}, Fill: ${JSON.stringify(node.fills)}, Strokes: ${JSON.stringify(node.strokes)}`;
  }

  figma.closePlugin(`Button:\n${inspectProps(btn)}\n\nText Field:\n${inspectProps(tf)}`);
}
